 const [detail,setDetail]=useState<Detail|null>(initialRunId?{type:'run',id:initialRunId}:initialAgentId?{type:'agent',id:initialAgentId}:null),[detailTab,setDetailTab]=useState(initialAgentId&&!initialRunId?'Workflow':'Overview'),[modal,setModal]=useState<Modal|null>(null),[toast,setToast]=useState(''),[working,setWorking]=useState(false);
 const [note,setNote]=useState(''),[assignee,setAssignee]=useState(''),[formError,setFormError]=useState(''),[testResult,setTestResult]=useState<{ok:boolean;message:string}|null>(null);
 const [draft,setDraft]=useState<ConnectorDraft>({name:'',type:'MCP',framework:'CrewAI',endpoint:'https://agent.example.invalid/mcp'});
 const requestVersion=useRef(0);
 async function reload(simulatedFailure=false){const v=++requestVersion.current;setRefreshing(true);setError('');try{if(simulatedFailure)throw Error('Simulated service interruption. Your demo records are preserved.');const s=await service.load();if(v===requestVersion.current)setRaw(s)}catch(e:any){if(v===requestVersion.current)setError(e.message)}finally{if(v===requestVersion.current){setLoading(false);setRefreshing(false)}}}
 useEffect(()=>{reload();const unsubscribe=service.subscribe(()=>reload());return()=>{requestVersion.current++;unsubscribe()}},[]);
